package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/rand"
	"net"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// --- reference HTTP policy (shared by all Go reference solutions) -----------
// Same criteria as the Python references (draft Section IV-F): bounded
// attempts (a context deadline covers connect, headers and body) within the
// call's deadline; capped exponential backoff with full jitter (100 ms
// floor); Retry-After respected; a request that may have reached the server
// is repeated only if it is idempotent or carries an idempotency key.
// refMutant selects one deliberately broken variant (references/README.md).

const refMutant = "FIXED_BACKOFF"

const (
	refConnectTimeout = 2 * time.Second
	refAttemptTimeout = 3 * time.Second
	refBaseDelay      = 500 * time.Millisecond
	refMaxDelay       = 4 * time.Second
	refMinDelay       = 100 * time.Millisecond
	refMaxAttempts    = 6 // per logical call (TIGHT_LOOP removes this cap too)
	refMinAttempt     = 300 * time.Millisecond // no attempt starts with less time than this left
)

var refClient = func() *http.Client {
	if refMutant == "NO_TIMEOUT" {
		return &http.Client{Transport: &http.Transport{Proxy: nil, MaxIdleConnsPerHost: 16}}
	}
	return &http.Client{Transport: &http.Transport{
		DialContext:         (&net.Dialer{Timeout: refConnectTimeout}).DialContext,
		TLSHandshakeTimeout: refConnectTimeout,
		MaxIdleConnsPerHost: 16,
	}}
}()

type refResp struct {
	Status   int
	Header   http.Header
	Body     []byte
	Attempts int
}

func (r *refResp) JSON(v any) error { return json.Unmarshal(r.Body, v) }

var errRefGiveUp = errors.New("giving up")

type refReq struct {
	Method     string
	URL        string
	Body       []byte
	Header     func(attempt int) http.Header
	Idempotent bool
	// Sink returns a fresh writer for the body of a 200 response of this attempt.
	Sink func(attempt int) (io.Writer, error)
}

func refRetryable(status int) bool {
	return status == 429 || status == 502 || status == 503 || status == 504
}

// refNotSent: the request certainly did not reach the server (dial failed).
func refNotSent(err error) bool {
	var oe *net.OpError
	return errors.As(err, &oe) && oe.Op == "dial"
}

func refRetryAfter(h http.Header) (time.Duration, bool) {
	v := strings.TrimSpace(h.Get("Retry-After"))
	if v == "" || refMutant == "IGNORE_RETRY_AFTER" {
		return 0, false
	}
	if n, err := strconv.Atoi(v); err == nil && n >= 0 {
		return time.Duration(n) * time.Second, true
	}
	if t, err := http.ParseTime(v); err == nil {
		d := time.Until(t)
		if d < 0 {
			d = 0
		}
		return d, true
	}
	return 0, false
}

func refDelay(attempt int) time.Duration {
	exp := refBaseDelay << attempt
	if exp > refMaxDelay || exp <= 0 {
		exp = refMaxDelay
	}
	switch refMutant {
	case "TIGHT_LOOP":
		return 0
	case "FIXED_BACKOFF": // the same capped exponential schedule, without jitter
		return exp
	}
	if exp < refMinDelay {
		exp = refMinDelay
	}
	// full jitter over [floor, cap(base * 2^k)]: uniform, no point mass at the floor
	return refMinDelay + time.Duration(rand.Float64()*float64(exp-refMinDelay))
}

func refAttempt(ctx context.Context, q refReq, attempt int) (*refResp, error) {
	var body io.Reader
	if q.Body != nil {
		body = bytes.NewReader(q.Body)
	}
	req, err := http.NewRequestWithContext(ctx, q.Method, q.URL, body)
	if err != nil {
		return nil, err
	}
	if q.Header != nil {
		for k, vs := range q.Header(attempt) {
			for _, v := range vs {
				req.Header.Add(k, v)
			}
		}
	}
	resp, err := refClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	out := &refResp{Status: resp.StatusCode, Header: resp.Header}
	if q.Sink != nil && resp.StatusCode == 200 {
		w, err := q.Sink(attempt)
		if err != nil {
			return nil, err
		}
		if _, err := io.Copy(w, resp.Body); err != nil {
			return nil, err
		}
		return out, nil
	}
	out.Body, err = io.ReadAll(resp.Body)
	return out, err
}

// refCall performs q with the reference policy before deadline.
func refCall(deadline time.Time, q refReq) (*refResp, error) {
	var last error
	for attempt := 0; ; attempt++ {
		ctx := context.Background()
		cancel := func() {}
		if refMutant != "NO_TIMEOUT" {
			remaining := time.Until(deadline)
			if remaining < refMinAttempt {
				return nil, fmt.Errorf("%w: deadline reached: %v", errRefGiveUp, last)
			}
			if remaining > refAttemptTimeout {
				remaining = refAttemptTimeout
			}
			ctx, cancel = context.WithTimeout(ctx, remaining)
		}
		r, err := refAttempt(ctx, q, attempt)
		cancel()
		var wait time.Duration
		hasRA := false
		if err == nil {
			r.Attempts = attempt + 1
			if !refRetryable(r.Status) {
				return r, nil
			}
			last = fmt.Errorf("HTTP %d", r.Status)
			wait, hasRA = refRetryAfter(r.Header)
		} else {
			last = err
			if !refNotSent(err) && !q.Idempotent && refMutant != "UNSAFE_POST_RETRY" {
				return nil, fmt.Errorf("%w: outcome unknown, not retried: %v", errRefGiveUp, err)
			}
		}
		if attempt+1 >= refMaxAttempts && refMutant != "TIGHT_LOOP" {
			return nil, fmt.Errorf("%w: %d attempts failed: %v", errRefGiveUp, refMaxAttempts, last)
		}
		d := refDelay(attempt)
		if hasRA && wait > d {
			d = wait
		}
		if refMutant != "NO_TIMEOUT" && time.Now().Add(d).After(deadline.Add(-refMinAttempt)) {
			return nil, fmt.Errorf("%w: no time left to retry after %v", errRefGiveUp, last)
		}
		time.Sleep(d)
	}
}

func refDeadline(budget time.Duration) time.Time { return time.Now().Add(budget) }

// --- end of reference HTTP policy ---------------------------------------------

func ListAllOrders(baseURL, customerID string) ([]map[string]any, error) {
	dl := refDeadline(9500 * time.Millisecond)
	base := baseURL + "/v1/customers/" + url.PathEscape(customerID) + "/orders"
	var all []map[string]any
	cursor := ""
	for {
		u := base
		if cursor != "" {
			u += "?cursor=" + url.QueryEscape(cursor)
		}
		r, err := refCall(dl, refReq{Method: "GET", URL: u, Idempotent: true})
		if err != nil {
			return nil, fmt.Errorf("orders: %w", err)
		}
		if r.Status != 200 {
			return nil, fmt.Errorf("orders: HTTP %d", r.Status)
		}
		var page struct {
			Orders []map[string]any `json:"orders"`
			Next   *string          `json:"next_cursor"`
		}
		if err := r.JSON(&page); err != nil {
			return nil, err
		}
		all = append(all, page.Orders...)
		if page.Next == nil || *page.Next == "" {
			return all, nil
		}
		cursor = *page.Next
	}
}
